import AppKit

/// "Enhance the microphone when it lands" (road map "audio" AP6 part 3, spec
/// §11 AU-68, AU-69): Enhance Voice run over a finished recording's VOICE
/// clips as a follow-up to the landing — never part of it. The landing commits
/// at once and is unchanged (`RecordingLanding`, `untitled(around:)`, the step
/// names, the notes); Enhance follows as its own undo step, "Enhance Voice",
/// once the voice's loudness and speech caches exist, because neither can
/// exist before the media is in a project.
///
/// The values and the pure decision are here: which files are the voice
/// (`voicePaths`), which clips they became (`voiceClips`), whether those are
/// measured (`isAnalysed`) and whether the document is in a state to take an
/// edit (`isBusy`), and `decide`. The two doors share them: the panel through
/// `follow` — a repeating timer per landing, in the run loop's DEFAULT mode
/// (the landing's retry trick: a drag runs the loop in tracking mode, so the
/// timer waits for it) — and `record_screen {enhance}` through
/// `AgentServer.landAndEnhance`, which polls `decide` from the server thread.
///
/// **The follow ends before anything is shown.** On any step but `.wait` the
/// timer is invalidated and the landing's pending entry removed FIRST, then
/// the step acts (`tick`): Cancel on the Measuring Sound sheet, no outcome or
/// a stale answer can never leave a timer that puts the sheet back up, and
/// `isPending` never depends on the sheet.
enum RecordingEnhance {
    /// One check every half second, the landing's own retry interval.
    static let checkInterval: TimeInterval = RecorderPanelController.landingRetryInterval
    /// Past this since the landing, a voice still unmeasured is given up on.
    static let waitLimit: TimeInterval = 300

    static let notReadyHead =
        "Enhance Voice did not run on the recording: its microphone was not ready to measure "
        + "within 5 minutes."
    static let notReadySentence = notReadyHead + " Select its clip and choose Clip ▸ Enhance Voice."
    /// The tool's `.giveUp` sentence: the same head, a tool's way out.
    static let notReadyToolSentence = notReadyHead + " Call enhance_voice with its clips."
    static let noVoiceSentence =
        "No microphone clip landed on the timeline, so there was nothing to enhance."
    /// The panel box's tooltip (AU-69 (a)), naming AU-68's step.
    static let boxTooltip =
        "After the recording lands, run Clip ▸ Enhance Voice on the microphone's clip as its own "
        + "undo step, \"Enhance Voice\", once its sound has been analyzed."

    /// What one check decides (AU-68 (d)).
    enum Step: Equatable {
        case wait
        case enhance([UInt32])
        case drop
        case giveUp
    }

    // MARK: - The voice

    /// The recording's voice files: each segment's microphone file, each
    /// left-out segment's readable microphone file, and for a voice-over each
    /// segment's own file — never the picture, the camera or the system audio.
    /// None without a microphone. Pure; empty paths dropped, each path once.
    static func voicePaths(of result: RecordingResult) -> [String] {
        guard result.choice.microphone != nil else { return [] }
        var paths = result.segments.compactMap { $0.micDescriptor?.path }
        paths += result.unreadable.compactMap { $0.micDescriptor?.path }
        if result.isVoiceOver { paths += result.segments.map { $0.descriptor.path } }
        var seen: Set<String> = []
        return paths.filter { !$0.isEmpty && seen.insert($0).inserted }
    }

    /// Every clip in the open container whose media is one of the voice
    /// files, in clip-id order. Main, after the landing's commit.
    static func voiceClips(of result: RecordingResult, in document: ProjectDocument) -> [UInt32] {
        let paths = Set(voicePaths(of: result))
        guard !paths.isEmpty else { return [] }
        let snapshot = document.editedProject.snapshot
        return snapshot.clips.filter { clip in
            snapshot.media(for: clip).map { paths.contains($0.path) } ?? false
        }.map(\.id).sorted()
    }

    /// The landing's container: the nest `scope` names, or the top level (#458). A follow-up
    /// reads its clips here, never in the open container, so a nest opened during its wait is
    /// busy rather than a drop. The open container's own view when it is the landing's. Main.
    static func container(of document: ProjectDocument, scope: UInt32?) -> ReelProject {
        if document.scope == scope { return document.editedProject }
        return scope.flatMap { document.project.scoped($0) } ?? document.project
    }

    /// The clips still in the landing's container. Main.
    static func present(_ clips: [UInt32], in document: ProjectDocument, scope: UInt32?)
        -> [UInt32]
    {
        let snapshot = container(of: document, scope: scope).snapshot
        return clips.filter { snapshot.clip($0) != nil }
    }

    /// Each clip's media has a current loudness cache, and its speech saved,
    /// or a current speech cache, or no speech model at all (AU-68 (b)). False
    /// for no clips, a missing file or no cache folder. The clips are read in the landing's
    /// container. Main.
    static func isAnalysed(_ clips: [UInt32], in document: ProjectDocument, scope: UInt32?)
        -> Bool
    {
        guard !clips.isEmpty, let cacheDir = document.cacheDirectory else { return false }
        let snapshot = container(of: document, scope: scope).snapshot
        for id in clips {
            guard let clip = snapshot.clip(id), let media = snapshot.media(for: clip),
                let url = mediaURL(for: media)
            else { return false }
            let stamp = MediaImporter.CacheStamp.stamp(for: media, url: url)
            guard MediaImporter.loudnessIsCurrent(for: media, stamp: stamp, in: cacheDir) else {
                return false
            }
            guard media.speech != nil
                || MediaImporter.speechIsCurrent(for: media, stamp: stamp, in: cacheDir)
                || !SileroVAD.isAvailable
            else { return false }
        }
        return true
    }

    /// A drag in progress, or the open container is not the landing's. The
    /// panel adds its own window test in `tick`. Main.
    static func isBusy(_ document: ProjectDocument, scope: UInt32?) -> Bool {
        document.isLiveEditing || document.scope != scope
    }

    /// AU-68 (d), in this order. Pure.
    static func decide(clips: [UInt32], analysed: Bool, busy: Bool, elapsed: TimeInterval) -> Step {
        if clips.isEmpty { return .drop }
        if analysed && !busy { return .enhance(clips) }
        if elapsed >= waitLimit { return .giveUp }
        return .wait
    }

    // MARK: - The panel's follow

    /// One landing's follow: its document, its clips, the scope it landed in,
    /// when, and the timer.
    private final class Follow {
        weak var document: ProjectDocument?
        var clips: [UInt32]
        var scope: UInt32?
        var started: Date
        var timer: Timer?

        init(document: ProjectDocument, clips: [UInt32], scope: UInt32?) {
            self.document = document
            self.clips = clips
            self.scope = scope
            self.started = Date()
        }
    }

    /// The follows under way, by the document's `recipeKey` (never minted
    /// twice). A second landing into a document with a follow under way joins
    /// it: its clips are added and the clock and scope start again.
    private static var follows: [Int: Follow] = [:]

    /// The panel's landing hands its result here once it has committed. A
    /// no-op unless the choice asked for it. Main.
    static func follow(_ result: RecordingResult, in document: ProjectDocument) {
        guard result.choice.enhanceMicrophone else { return }
        let clips = voiceClips(of: result, in: document)
        let key = document.recipeKey
        if let pending = follows[key] {
            pending.clips = Array(Set(pending.clips + clips)).sorted()
            pending.scope = document.scope
            pending.started = Date()
            return
        }
        let follow = Follow(document: document, clips: clips, scope: document.scope)
        follows[key] = follow
        // `scheduledTimer` adds it in the DEFAULT mode: it waits out a drag.
        follow.timer = Timer.scheduledTimer(withTimeInterval: checkInterval, repeats: true) {
            [weak document] timer in
            guard let document else {
                timer.invalidate()
                follows[key] = nil
                return
            }
            tick(document)
        }
    }

    /// True only while a follow's timer runs for `document`. Main.
    static func isPending(_ document: ProjectDocument) -> Bool {
        follows[document.recipeKey] != nil
    }

    /// The timer of `document`'s follow, nil with none — what the probe reads
    /// back after a step (P5). Main.
    static func timer(of document: ProjectDocument) -> Timer? {
        follows[document.recipeKey]?.timer
    }

    /// One firing: decide, and on any step but `.wait` end the follow FIRST
    /// (the type doc), then act. Main.
    static func tick(_ document: ProjectDocument) {
        guard let follow = follows[document.recipeKey] else { return }
        let clips = present(follow.clips, in: document, scope: follow.scope)
        let window = RecorderPanelController.editor(of: document)?.view.window
        let busy =
            isBusy(document, scope: follow.scope) || window == nil || window?.attachedSheet != nil
        let step = decide(
            clips: clips, analysed: isAnalysed(clips, in: document, scope: follow.scope),
            busy: busy,
            elapsed: Date().timeIntervalSince(follow.started))
        guard step != .wait else { return }
        end(follow, key: document.recipeKey)
        switch step {
        case .enhance(let ids):
            guard let window else { return refuse(notReadySentence, in: document) }
            AudioMeasureDoor.enhanceLanded(document: document, clips: ids, window: window)
        case .giveUp:
            refuse(notReadySentence, in: document)
        case .drop, .wait:
            break
        }
    }

    private static func end(_ follow: Follow, key: Int) {
        follow.timer?.invalidate()
        follows[key] = nil
    }

    /// A refusal of `enhance_voice` at the inspector's foot; no beep (AU-68 (e)).
    static func refuse(_ reason: String, in document: ProjectDocument) {
        NotificationCenter.default.post(
            name: .projectDocumentDidRefuse, object: document,
            userInfo: [
                "refusal": ReelRefusal(op: AudioMeasureDoor.Command.enhanceVoice.tool, reason: reason)
            ])
    }
}

import AppKit

/// The recorder panel's polish follow (road map "creator-jobs" CU10, spec §11 CU-101 (f)…(i)):
/// a repeating timer per LANDING — never joined with another, unlike Enhance's — in the run
/// loop's DEFAULT mode, so a drag (tracking mode) holds it. Each firing decides for the first
/// command still to run; the follow ends FIRST, its timer invalidated and its entry removed, on
/// `.drop`, on `.giveUp`, before the last run, or when the cursor files fail to read, and then
/// the step acts. A refusal from one run moves on to the next command, whose clock starts then.
///
/// The panel's settings are what each menu door would use (CU-101 (g)): Auto Zoom's remembered
/// sheet values with Zoom on typing on whenever the files hold typing, the overlays' defaults
/// and Speed Up Typing's remembered sheet values. Nothing here asks: a plan with no ops and a
/// `.drop` are quiet, and a refusal, a give-up or a read failure is said at the inspector's foot
/// (`projectDocumentDidRefuse`), with no beep and no sheet (CU-101 (h)). A timer is not an
/// AppKit event, so every commit is `performGroupedEdit`.
extension RecordingPolish {
    /// One landing's follow.
    private final class Follow {
        weak var document: ProjectDocument?
        let paths: [String]
        let scope: UInt32?
        var commands: [Command]
        var started = Date()
        var enhancing = false
        /// The cursor files, by media id, once read; `reading` while a read is out.
        var tracks: [UInt32: ReelCursor]?
        var reading = false
        var timer: Timer?

        init(document: ProjectDocument, paths: [String], scope: UInt32?, commands: [Command]) {
            self.document = document
            self.paths = paths
            self.scope = scope
            self.commands = commands
        }
    }

    /// The follows under way, by a number minted per landing.
    private static var follows: [Int: Follow] = [:]
    private static var minted = 0

    /// The panel's landing hands its result here once it has committed (after Enhance's
    /// follow). A no-op unless the choice asks for a command. Main.
    static func follow(_ result: RecordingResult, in document: ProjectDocument) {
        let asked = commands(of: result.choice)
        guard !asked.isEmpty else { return }
        minted += 1
        let id = minted
        let follow = Follow(
            document: document, paths: screenPaths(of: result), scope: document.scope,
            commands: asked)
        follows[id] = follow
        // `scheduledTimer` adds it in the DEFAULT mode: it waits out a drag.
        follow.timer = Timer.scheduledTimer(withTimeInterval: checkInterval, repeats: true) {
            [weak document] timer in
            guard let document else {
                timer.invalidate()
                follows[id] = nil
                return
            }
            tick(id, document)
        }
    }

    /// True while any follow of `document` runs. Main.
    static func isPending(_ document: ProjectDocument) -> Bool {
        follows.values.contains { $0.document === document }
    }

    /// One firing. Main.
    private static func tick(_ id: Int, _ document: ProjectDocument) {
        guard let follow = follows[id], let command = follow.commands.first else {
            return end(id, document)
        }
        let clips = screenClips(follow.paths, in: document, scope: follow.scope)
        // CU-101 (a): the clock restarts when Enhance Voice's follow ends.
        let enhancing = RecordingEnhance.isPending(document)
        if follow.enhancing && !enhancing { follow.started = Date() }
        follow.enhancing = enhancing
        let media = mediaIDs(clips, in: document, scope: follow.scope)
        if !clips.isEmpty, !follow.reading,
            follow.tracks.map({ !media.isSubset(of: Set($0.keys)) }) ?? true
        {
            read(id, follow, clips, in: document)
        }
        let window = RecorderPanelController.editor(of: document)?.view.window
        let busy =
            RecordingEnhance.isBusy(document, scope: follow.scope) || window == nil
            || window?.attachedSheet != nil
        // `isReady` reads the open container, so only when it is the landing's (#458).
        let ready =
            !busy
            && follow.tracks.map { tracks in
                media.isSubset(of: Set(tracks.keys))
                    && isReady(
                        command, clips: clips, tracks: tracks,
                        speedUp: SpeedUpTypingSettings.remembered(.standard), in: document)
            } ?? false
        let step = decide(
            command: command, clips: clips, enhancing: enhancing, ready: ready, busy: busy,
            elapsed: Date().timeIntervalSince(follow.started))
        switch step {
        case .wait:
            return
        case .drop:
            end(id, document)
        case .giveUp(let given):
            end(id, document)
            refuse(given, notReadySentence(given, tool: false), in: document)
        case .run(let ran, let ids):
            follow.commands.removeFirst()
            follow.started = Date()
            if follow.commands.isEmpty { end(id, document) }
            if let reason = run(ran, clips: ids, tracks: follow.tracks ?? [:], in: document) {
                refuse(ran, reason, in: document)
            }
        }
    }

    /// The media ids of `clips` in the landing's container. Main.
    private static func mediaIDs(_ clips: [UInt32], in document: ProjectDocument, scope: UInt32?)
        -> Set<UInt32>
    {
        let snapshot = RecordingEnhance.container(of: document, scope: scope).snapshot
        return Set(clips.compactMap { snapshot.clip($0).flatMap { snapshot.media(for: $0)?.id } })
    }

    /// The clips' cursor files read on a global queue, once; a failure ends the follow and is
    /// said under the command it was read for. Main.
    private static func read(
        _ id: Int, _ follow: Follow, _ clips: [UInt32], in document: ProjectDocument
    ) {
        let snapshot = RecordingEnhance.container(of: document, scope: follow.scope).snapshot
        let files: [UInt32: URL]
        do {
            files = try AutoZoom.cursorFiles(clips.compactMap { snapshot.clip($0) }, in: snapshot)
        } catch {
            return failRead(id, follow, error, in: document)
        }
        follow.reading = true
        DispatchQueue.global(qos: .userInitiated).async {
            let read = Result { try AutoZoom.readTracks(files) }
            DispatchQueue.main.async { [weak document] in
                follow.reading = false
                guard let document, follows[id] === follow else { return }
                switch read {
                case .success(let tracks): follow.tracks = tracks
                case .failure(let error): failRead(id, follow, error, in: document)
                }
            }
        }
    }

    private static func failRead(
        _ id: Int, _ follow: Follow, _ error: Error, in document: ProjectDocument
    ) {
        let command = follow.commands.first ?? .autoZoom
        end(id, document)
        refuse(command, error.localizedDescription, in: document)
    }

    private static func end(_ id: Int, _ document: ProjectDocument) {
        follows[id]?.timer?.invalidate()
        follows[id] = nil
        forgetWait(document)
    }

    // MARK: - The three runs

    /// Plans `command` over `clips` and commits it as one grouped step; nil when it applied or
    /// had nothing to do, else the sentence to say. Main.
    private static func run(
        _ command: Command, clips ids: [UInt32], tracks: [UInt32: ReelCursor],
        in document: ProjectDocument
    ) -> String? {
        let snapshot = document.editedProject.snapshot
        let clips = ids.compactMap { snapshot.clip($0) }
        do {
            switch command {
            case .autoZoom:
                var settings = AutoZoomSettings.remembered(.standard)
                settings.typing = AutoZoom.hasTyping(tracks)
                let plan = try AutoZoom.plan(
                    clips, tracks: tracks, project: document.editedProject, settings: settings,
                    from: nil, to: nil)
                guard !plan.ops.isEmpty else { return nil }
                document.performGroupedEdit(AutoZoom.actionName, plan.ops)
            case .shortcutOverlays:
                let planned = try ShortcutOverlays.prepared(
                    document, clips: ids, tracks: tracks, settings: ShortcutOverlaySettings(),
                    from: nil, to: nil)
                guard !planned.plan.ops.isEmpty else { return nil }
                document.performGroupedEdit(ShortcutOverlays.actionName, planned.plan.ops)
            case .speedUpTyping:
                return try speedUp(clips, tracks: tracks, in: document)
            }
        } catch {
            return error.localizedDescription
        }
        return nil
    }

    /// CU-101 (i): the panel cannot ask Set Speed, so a speed-up that would leave a clip's audio
    /// out is not applied and its note is the refusal; otherwise one grouped step, the captions
    /// it re-times riding in it.
    private static func speedUp(
        _ clips: [ClipSnapshot], tracks: [UInt32: ReelCursor], in document: ProjectDocument
    ) throws -> String? {
        let outcome = try SpeedUpTyping.resolve(
            clips, tracks: tracks, project: document.editedProject,
            cacheDirectory: document.cacheDirectory,
            settings: SpeedUpTypingSettings.remembered(.standard), from: nil, to: nil)
        guard case .planned(let speechOps, let plan) = outcome else {
            return notReadySentence(.speedUpTyping, tool: false)
        }
        guard !plan.ops.isEmpty else { return nil }
        let step = CaptionRetime.withRetime(
            SpeedUpTyping.actionName, speechOps + plan.ops, on: document.editedProject)
        let crossing =
            SpeedAudioDrop.mayCross(step.ops)
            ? SpeedAudioDrop.crossing(applying: step.ops, to: document.editedProject) : []
        guard crossing.isEmpty else { return SpeedAudioDrop.note(crossing) }
        document.performGroupedEdit(step.name, step.ops)
        return nil
    }

    /// A refusal of `command` at the inspector's foot; no beep (CU-101 (h)).
    private static func refuse(_ command: Command, _ reason: String, in document: ProjectDocument) {
        NotificationCenter.default.post(
            name: .projectDocumentDidRefuse, object: document,
            userInfo: ["refusal": ReelRefusal(op: command.rawValue, reason: reason)])
    }
}

import AppKit

/// The one body the Volume section's buttons and the Clip menu share for
/// Normalize and Enhance Voice (road map "audio" AP6, spec §11 AU-60,
/// AU-64, AU-65), and Clip ▸ Match Audio…'s after its sheet (AP12,
/// `pressMatch`, AU-128). Not a line of arithmetic is here: the read, the
/// jobs and the plan are `AudioNormalize`'s, `AudioEnhance`'s and
/// `AudioMatch`'s, the measurement is `LoudnessMeasureRun`'s or
/// `AudioMatchRun`'s, and this decides only how a press waits and commits.
///
/// - **Normalize in Peak mode** commits `AudioNormalize.plan(read).ops` at
///   once, inside the event, exactly as before: no run, no render, no sheet.
/// - **Normalize in Loudness mode and Enhance Voice** build a run. When no
///   clip needs a render the run answers at once and the plan is committed
///   inside the event (`applyEdit`), today's Normalize byte for byte.
///   Otherwise the Measuring Sound sheet goes up from the window's content
///   controller, and its answer is committed with `performGroupedEdit` (a
///   sheet's completion is not an AppKit event, app/CLAUDE.md's undo
///   pitfall) only when the document's project and scope are still the ones
///   the press read; else it beeps and says so at the inspector's foot, as
///   `finishSynchronizeAudio` does.
///
/// Nothing to do, a second press, no window and a sheet already up all beep.
///
/// **A landing's follow** (spec §11 AU-68) is another caller:
/// `enhanceLanded`, Enhance Voice over a recording's voice clips once their
/// caches exist. It shares `measure`, with a refusal at the inspector's foot
/// wherever a press beeps, and commits as its own group, since a timer's
/// firing is not an AppKit event either.
enum AudioMeasureDoor {
    enum Command {
        case normalize, enhanceVoice, matchAudio

        var name: String {
            switch self {
            case .normalize: return "Normalize"
            case .enhanceVoice: return AudioEnhance.actionName
            case .matchAudio: return AudioMatch.actionName
            }
        }

        var tool: String {
            switch self {
            case .normalize: return "normalize_clip"
            case .enhanceVoice: return "enhance_voice"
            case .matchAudio: return "match_audio"
            }
        }
    }

    /// The sheet's title.
    static let sheetTitle = "Measuring Sound"

    /// The stale answer's sentence, ending in what to do again: "Choose
    /// Enhance Voice again." from the sheet, "Call enhance_voice again." from
    /// a tool.
    static func staleReason(again: String) -> String {
        "the project changed while its sound was being measured, so nothing changed. \(again)"
    }

    static func press(
        _ command: Command, document: ProjectDocument, clips: [UInt32], window: NSWindow?
    ) {
        guard !clips.isEmpty else { return NSSound.beep() }
        switch command {
        case .normalize where NormalizeChoice.mode == .peak:
            guard let input = AudioNormalize.read(from: document, clips: clips) else {
                return NSSound.beep()
            }
            commit(command.name, AudioNormalize.plan(input).ops, document: document)
        case .normalize:
            guard let input = AudioNormalize.readLoudness(from: document, clips: clips) else {
                return NSSound.beep()
            }
            let target = NormalizeChoice.targetLUFS
            let run = LoudnessMeasureRun(
                document: document, jobs: normalizeJobs(input, in: document),
                problems: input.problems, targetLUFS: target)
            measure(command, run: run, document: document, window: window) {
                .ops(AudioNormalize.plan($0.input, targetLUFS: target, solved: $0.solved).ops)
            }
        case .enhanceVoice:
            guard
                let setup = enhanceSetup(
                    document: document, clips: clips, targetLUFS: NormalizeChoice.targetLUFS)
            else { return NSSound.beep() }
            let run = setup.makeRun(document: document)
            measure(command, run: run, document: document, window: window) {
                .ops(setup.plan($0).ops)
            }
        case .matchAudio:
            // Its reference comes from the Match Audio sheet: `pressMatch`.
            NSSound.beep()
        }
    }

    /// Match Audio's press (road map "audio" AP12, spec §11 AU-121, AU-128),
    /// from the Match Audio sheet's hand-back: `reference` and the other
    /// clips, read, then always measured under the Measuring Sound sheet (the
    /// reference renders), its answer landed by `measure`'s stale test. A
    /// refusal — the reference's, or nothing to match — beeps once and puts
    /// its sentence at the inspector's foot, before the sheet or after it
    /// (AU-128, #410).
    static func pressMatch(
        document: ProjectDocument, reference: UInt32, clips: [UInt32], loudness: Bool, eq: Bool,
        window: NSWindow?
    ) {
        guard loudness || eq, !clips.isEmpty else { return NSSound.beep() }
        let input: AudioMatch.Input
        switch AudioMatch.read(
            from: document, reference: reference, clips: clips, loudness: loudness, eq: eq)
        {
        case .failure(let refusal):
            return say(
                refusal.sentence, command: .matchAudio, document: document,
                beep: { NSSound.beep() })
        case .success(let read): input = read
        }
        let run = AudioMatchRun(document: document, input: input)
        measure(
            .matchAudio, run: run, document: document, window: window,
            answer: { matchAnswer(input, $0) })
    }

    /// Match's answer to a run's outcome, pure: the reference's refusal,
    /// else "Nothing could be matched." with every skip when no target was
    /// matched after the renders (the tool's sentence), else the plan's ops.
    static func matchAnswer(_ input: AudioMatch.Input, _ outcome: AudioMatchRun.Outcome) -> Answer {
        if let refusal = outcome.refusal { return .refused(refusal.sentence) }
        let plan = AudioMatch.plan(input, outcome: outcome)
        guard !plan.matched.isEmpty else { return .refused(AudioMatch.nothingMatched(plan.skipped)) }
        return .ops(plan.ops)
    }

    /// Enhance Voice's one setup (AU-68 (e), #412), shared by the press, a
    /// landing's follow and `enhance_voice`: the read, the choices and the
    /// target. It builds no run: `makeRun` is called only after the caller's
    /// refusals, and its caller owes the run `finish()`.
    struct EnhanceSetup {
        let input: AudioEnhance.Input
        let choices: [AudioEnhance.Choice]
        let targetLUFS: Double

        /// The measurement run over the choices' jobs. Main.
        func makeRun(document: ProjectDocument) -> LoudnessMeasureRun {
            LoudnessMeasureRun(
                document: document, jobs: AudioEnhance.jobs(input, choices),
                problems: input.problems, targetLUFS: targetLUFS)
        }

        func plan(_ outcome: LoudnessMeasureRun.Outcome) -> AudioEnhance.Plan {
            AudioEnhance.plan(input, choices: choices, outcome: outcome, targetLUFS: targetLUFS)
        }
    }

    /// Main. Nil when the project's audio plan cannot be read.
    static func enhanceSetup(document: ProjectDocument, clips: [UInt32], targetLUFS: Double)
        -> EnhanceSetup?
    {
        guard let input = AudioEnhance.read(from: document, clips: clips) else { return nil }
        return EnhanceSetup(
            input: input, choices: AudioEnhance.choose(input), targetLUFS: targetLUFS)
    }

    /// Enhance Voice over a landed recording's voice clips (AU-68 (e)), at
    /// Normalize's target: the press's setup and `measure` with refusals in
    /// place of beeps, nothing called back. Main.
    static func enhanceLanded(document: ProjectDocument, clips: [UInt32], window: NSWindow) {
        let refuse = { (reason: String) in RecordingEnhance.refuse(reason, in: document) }
        guard
            let setup = enhanceSetup(
                document: document, clips: clips, targetLUFS: NormalizeChoice.targetLUFS)
        else {
            return refuse(
                "The project's audio plan could not be read, so there is no voice to measure.")
        }
        guard !setup.input.isEmpty else { return refuse(nothingReason(setup.input.problems)) }
        let run = setup.makeRun(document: document)
        measure(
            .enhanceVoice, run: run, document: document, window: window, refuse: refuse,
            empty: { nothingReason(setup.plan($0).skipped) }
        ) { .ops(setup.plan($0).ops) }
    }

    /// `enhance_voice`'s sentence for nothing measured or nothing planned.
    static func nothingReason(_ problems: [AudioNormalize.Problem]) -> String {
        "Nothing could be enhanced. " + problems.map { $0.description }.joined(separator: " ")
    }

    /// Loudness Normalize's jobs: a clip whose chain has a stage the cache
    /// leaves out renders with no change to its settings (the run takes its
    /// limiter off for R0); any other reading stands (AU-64 (a)). Main.
    static func normalizeJobs(_ input: AudioNormalize.LoudnessInput, in document: ProjectDocument)
        -> [LoudnessMeasureRun.Job]
    {
        let snapshot = document.editedProject.snapshot
        return input.readings.map {
            LoudnessMeasureRun.Job(
                reading: $0,
                chain: ProcessedLoudness.needsRender(snapshot.clip($0.clip)?.audio)
                    ? AudioPatch() : nil)
        }
    }

    /// What a measured press answers: the ops to commit, or a refusal's
    /// sentence known only after the measurement.
    enum Answer {
        case ops([ReelOp])
        case refused(String)
    }

    /// The one landing of a measured answer, on main. `.refused` says its
    /// sentence once: through `refuse` on a landing's follow, else one `beep`
    /// and the sentence at the inspector's foot (`say`). `.ops([])` fails
    /// with `empty()`: `refuse` gets it, or a press gets a bare beep.
    /// Otherwise it commits: `applyEdit` when `inEvent` and `refuse` is nil
    /// (which beeps at an identity), else `performGroupedEdit`. `beep` is the
    /// probe's seam; the app passes none.
    static func land(
        _ answer: Answer, command: Command, document: ProjectDocument, inEvent: Bool,
        refuse: ((String) -> Void)?, empty: @autoclosure () -> String,
        beep: () -> Void = { NSSound.beep() }
    ) {
        switch answer {
        case .refused(let reason):
            if let refuse { return refuse(reason) }
            say(reason, command: command, document: document, beep: beep)
        case .ops(let ops):
            guard !ops.isEmpty else {
                if let refuse { return refuse(empty()) }
                return beep()
            }
            if inEvent, refuse == nil {
                document.applyEdit(command.name, ops)
            } else {
                document.performGroupedEdit(command.name, ops)
            }
        }
    }

    /// One beep and `reason` at the inspector's foot, as `command`'s tool.
    private static func say(
        _ reason: String, command: Command, document: ProjectDocument, beep: () -> Void
    ) {
        beep()
        NotificationCenter.default.post(
            name: .projectDocumentDidRefuse, object: document,
            userInfo: ["refusal": ReelRefusal(op: command.tool, reason: reason)])
    }

    /// Runs `run` at once when nothing renders, else under the sheet, and
    /// lands `answer` of its outcome through `land`. With `refuse` (a
    /// landing's follow) each beep is that refusal instead — `empty` says
    /// why nothing was planned — and the commit is grouped.
    private static func measure<Run: AudioMeasureRunning>(
        _ command: Command, run: Run, document: ProjectDocument,
        window: NSWindow?, refuse: ((String) -> Void)? = nil,
        empty: ((Run.Outcome) -> String)? = nil,
        answer: @escaping (Run.Outcome) -> Answer
    ) {
        let stopped = "\(command.tool) was stopped while its sound was being measured."
        guard run.needsRender else {
            // No render: the run answers before `start` returns, inside the event.
            run.start { outcome in
                guard let outcome else { return fail(refuse, stopped) }
                land(
                    answer(outcome), command: command, document: document, inEvent: true,
                    refuse: refuse, empty: empty?(outcome) ?? stopped)
            }
            run.finish()
            return
        }
        guard let window, window.attachedSheet == nil, let host = window.contentViewController
        else {
            run.finish()
            return fail(refuse, "A sheet was already up on the project's window, so nothing changed.")
        }
        let asked = document.project
        let scope = document.scope
        host.presentAsSheet(
            AudioMeasureSheetController(run: run, title: sheetTitle) { [weak document] outcome in
                defer { run.finish() }
                guard let document else { return }
                let stale = document.project !== asked || document.scope != scope
                land(
                    stale
                        ? .refused(staleReason(again: "Choose \(command.name) again."))
                        : answer(outcome),
                    command: command, document: document, inEvent: false, refuse: refuse,
                    empty: empty?(outcome) ?? stopped)
            })
    }

    /// The press beeps; a landing's follow says `reason` at the inspector's foot.
    private static func fail(_ refuse: ((String) -> Void)?, _ reason: String) {
        guard let refuse else { return NSSound.beep() }
        refuse(reason)
    }

    /// Inside the event: `applyEdit`, which beeps at an identity; an empty
    /// list beeps here.
    private static func commit(_ name: String, _ ops: [ReelOp], document: ProjectDocument) {
        guard !ops.isEmpty else { return NSSound.beep() }
        document.applyEdit(name, ops)
    }
}

import AppKit

/// The Measuring Sound sheet (road map "audio" AP6, spec §11 AU-65): up
/// while a `LoudnessMeasureRun` renders its clips through their chains
/// (AU-64), or an `AudioMatchRun` its reference and targets (AU-128), so the
/// window never beach-balls on a long clip. It takes any
/// `AudioMeasureRunning`, held as the four closures below.
/// `AudioSyncSheetController`'s shape: a bar, "Clip n of N…" and Cancel.
///
/// The run was built on the main thread from what the press read; the sheet
/// starts it when it appears. While the sheet is attached every editor action
/// validates false (`EditorViewController.validateUserInterfaceItem`), the
/// bargain Synchronize Audio strikes. When the outcome comes back the sheet
/// keeps it and dismisses itself; `finished` is called once, on the main
/// queue's next turn after `viewDidDisappear`. Cancel stops the render in
/// flight, releases the run's render wants and dismisses at once: nothing
/// changes.
final class AudioMeasureSheetController: NSViewController {
    /// The run, type-erased: `begin` sets its progress and starts it,
    /// answering whether an outcome came back (kept for `deliver`).
    private let begin: (@escaping (Int, Int) -> Void, @escaping (Bool) -> Void) -> Void
    private let cancelRun: () -> Void
    private let finishRun: () -> Void
    private let deliver: () -> Void
    private let sheetTitle: String

    private let bar = NSProgressIndicator()
    private let statusLabel = NSTextField(wrappingLabelWithString: "")
    /// Set in `loadView`; implicitly unwrapped for exactly that reason
    /// (app/CLAUDE.md).
    private var cancelButton: NSButton!
    private var hiddenButton: NSButton!

    private var didStart = false
    private var cancelled = false
    private var answered = false
    private var hasOutcome = false

    init<Run: AudioMeasureRunning>(
        run: Run, title: String, finished: @escaping (Run.Outcome) -> Void
    ) {
        let box = AudioMeasureOutcomeBox<Run.Outcome>()
        begin = { progress, answered in
            run.progress = progress
            run.start { outcome in
                box.outcome = outcome
                answered(outcome != nil)
            }
        }
        cancelRun = { run.cancel() }
        finishRun = { run.finish() }
        deliver = {
            guard let outcome = box.outcome else { return }
            finished(outcome)
        }
        self.sheetTitle = title
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("AudioMeasureSheetController does not support NSCoder")
    }

    override func loadView() {
        styleSheetProgressBar(bar, indeterminate: true)

        styleSheetStatusLabel(statusLabel)
        statusLabel.stringValue = "Measuring the sound through each clip's processing…"

        let content = makeProgressStack([bar, statusLabel])

        cancelButton = StickerButton(
            title: "Cancel", style: .secondary, target: self, action: #selector(cancelClicked(_:)))
        hiddenButton = StickerButton(title: "Apply", style: .primary, target: nil, action: nil)
        hideReturnTarget(hiddenButton)

        view = makeSheetView(
            title: sheetTitle,
            hint: "Nothing changes until every clip is measured; Cancel leaves everything as "
                + "it is.",
            content: content, buttonRow: makeButtonRow(cancel: cancelButton, apply: hiddenButton))
    }

    override func viewDidAppear() {
        super.viewDidAppear()
        guard !didStart else { return }
        didStart = true
        bar.startAnimation(nil)
        begin({ [weak self] clip, count in
            self?.statusLabel.stringValue = "Clip \(clip) of \(count)…"
        }) { [weak self] answered in
            guard let self, !self.cancelled else { return }
            guard answered else {
                self.cancelled = true
                self.finishRun()
                self.dismiss(self)
                return
            }
            self.hasOutcome = true
            self.dismiss(self)
        }
    }

    /// The one hand-back: once, with the outcome, and never after Cancel. On
    /// the next turn of the main queue, because while this runs the window
    /// still reports this sheet as attached.
    override func viewDidDisappear() {
        super.viewDidDisappear()
        bar.stopAnimation(nil)
        guard !answered, !cancelled, hasOutcome else { return }
        answered = true
        let deliver = self.deliver
        DispatchQueue.main.async { deliver() }
    }

    @objc private func cancelClicked(_ sender: Any?) {
        guard !cancelled, !hasOutcome else { return }
        cancelled = true
        cancelRun()
        finishRun()
        dismiss(self)
    }
}

